query ListTemplates($type: TemplateType) {
  templates(type: $type) {
    id
    name
    slug
    type
    isDefault
    status
  }
}

query GetTemplate($slug: String) {
  template(slug: $slug) {
    id
    name
    status
    zones {
      id
      slug
      orderIndex
      blocks {
        id
        blockType
        orderIndex
        config
        isActive
      }
    }
  }
}

mutation CreateTemplate($input: CreateTemplateInput!) {
  createTemplate(input: $input) {
    id
    slug
    status
  }
}

mutation CreateZone($input: CreateZoneInput!) {
  createZone(input: $input) {
    id
    slug
    orderIndex
  }
}

mutation AddBlock($input: CreateBlockInstanceInput!) {
  createBlockInstance(input: $input) {
    id
    blockType
    orderIndex
  }
}

mutation UpdateBlock($id: ID!, $input: UpdateBlockInstanceInput!) {
  updateBlockInstance(id: $id, input: $input) {
    id
    config
  }
}

mutation Reorder($zoneSlug: String!, $blockIds: [ID!]!) {
  reorderBlockInstances(zoneSlug: $zoneSlug, blockIds: $blockIds) {
    id
    orderIndex
  }
}

mutation Publish($id: ID!) {
  publishTemplate(id: $id) {
    id
    status
    publishedAt
  }
}

mutation Assign($pageId: ID!, $templateId: ID!) {
  assignTemplateToPage(pageId: $pageId, templateId: $templateId) {
    id
    slug
  }
}
